  const approved: Approval = { version: 1, kind: "storage-layout-v1", codeRevision: identity.codeRevision,
    approvedAt: now.toISOString(), proofHash, proof };
  // Keep every accepted measurement for audit; the small revision pointer may
  // advance only after its replacement has independently passed acceptance.
  await env.OPS_DB.prepare("INSERT INTO eod_rollout_evidence(id,evidence_json,updated_at) VALUES(?,?,?) ON CONFLICT(id) DO NOTHING")
    .bind(`history-storage-proof:${proofHash}`, JSON.stringify(approved), now.toISOString()).run();
  await write(env.OPS_DB, id, approved, now);
  await write(env.OPS_DB, `history-storage-status:${identity.codeRevision}`, cachedStatus(approved,null,now), now);
  return approved;
}

async function assertApproval(approved: Approval, revision: string): Promise<void> {
  if (approved.version !== 1 || approved.kind !== "storage-layout-v1" || approved.codeRevision !== revision
    || !digest(approved.proofHash) || await eodHash(approved.proof) !== approved.proofHash
    || approved.proof.identity.codeRevision !== revision || !Number.isFinite(Date.parse(approved.proof.horizon.expiresAt))) fail("approval-integrity");
}

function assertConfigCapacity(approved: Approval, proof: EodCutoverEvidence): void {
  const source = approved.proof;
  if (source.model.hotSessions !== 90 || proof.retention.hotSessions !== 90
    || proof.retention.sweepHeadroomSessions !== source.model.sweepHeadroomSessions
    || proof.runId !== source.publicationRunId || proof.sessionDate !== source.horizon.anchorSession
    || proof.sharedTickers.count !== source.tickers.length || proof.capacity.measuredAt !== source.capacity.measuredAt
    || proof.capacity.marketDatabaseBytes !== source.capacity.projectedMarketBytes
    || proof.capacity.archiveDatabaseBytes !== source.capacity.liveHistoryBytes
    || proof.capacity.archiveDatabaseBytes + proof.capacity.additionalArchiveBytes !== source.capacity.projectedHistoryBytes
    || proof.capacity.priceTableAndIndexBytes !== source.model.priceTableAndIndexBytes
    || proof.capacity.priceRows < source.model.modeledPriceRows
    || proof.readers.checkedAt !== source.readers.checkedAt || proof.readers.contractVersion !== source.readers.contractVersion
    || JSON.stringify(proof.readers.consumers) !== JSON.stringify(source.readers.consumers)) fail("config-capacity-mismatch");
}

/** A config-only commit can reference the exact immutable measured model from
 * its executor. It cannot refresh a measurement, extend the horizon or change
 * retention. The caller stores this reference only after the real Git diff and
 * complete current cutover proof have passed production-config validation. */
export async function storageHistoryConfigurationReference(env: Env, input: {
  sourceRevision: string; nextRevision: string; proof: EodCutoverEvidence; now?: Date;
}): Promise<{ historyCapacityProofHash: string }> {
  if (!/^[a-f0-9]{40}$/.test(input.nextRevision) || input.nextRevision === input.sourceRevision
    || input.proof.codeRevision !== input.nextRevision) fail("config-revision-invalid");
  const approved = await loadApproval({ ...env, EOD_CODE_REVISION: input.sourceRevision }, input.sourceRevision);
  if (!approved || approved.codeRevision !== input.sourceRevision) fail("config-source-approval-required");
  const now = input.now ?? new Date();
  if (now.getTime() < Date.parse(approved.approvedAt) || now.getTime() >= Date.parse(approved.proof.horizon.expiresAt)) fail("forecast-horizon-expired");
  assertConfigCapacity(approved, input.proof);
  const immutable = await read<Approval>(env.OPS_DB!, `history-storage-proof:${approved.proofHash}`);
  if (!immutable || await eodHash(immutable) !== await eodHash(approved)) fail("config-immutable-approval-required");
  return { historyCapacityProofHash: approved.proofHash };
}

async function loadApproval(env: Env, revision: string): Promise<Approval | null> {
  if (!env.OPS_DB) return null;
  if (env.EOD_CODE_REVISION !== revision) fail("approval-integrity");
  const direct = await read<Approval>(env.OPS_DB, `history-storage-approval:${revision}`);
  if (direct) { await assertApproval(direct, revision); return direct; }
  const transition = await read<Record<string, unknown>>(env.OPS_DB, `config-transition:${revision}`);
  if (!transition) return null;
  // Only the immutable record written by the strict one-file config transition
  // can bridge code identity. Resolve the pinned immutable proof, not a mutable
  // latest-approval pointer that might later refer to a different measurement.
  const original = transition.activationCodeRevision;
  if (transition.version !== 1 || transition.policy !== "canonical-config-only-v1" || transition.codeRevision !== revision
    || typeof original !== "string" || !/^[a-f0-9]{40}$/.test(original) || original === revision
    || !digest(transition.historyCapacityProofHash) || !digest(transition.proofHash)
    || !digest(transition.approvedConfigHash) || !digest(transition.candidateConfigHash) || !digest(transition.sourceProofHash)) fail("config-link-invalid");
  const approved = await read<Approval>(env.OPS_DB, `history-storage-proof:${transition.historyCapacityProofHash}`);
  if (!approved) fail("config-source-approval-required");
  await assertApproval(approved, original);
  const approval = await read<Record<string, unknown>>(env.OPS_DB, `active:${revision}`);
  // Defer this schema import: the rollout coordinator also imports historical
  // capacity, and eager initialization would capture an undefined scope enum.
  const { eodCutoverEvidenceSchema } = await import("./eod-rollout-service");
  const parsed = eodCutoverEvidenceSchema.safeParse(approval?.proof);
  if (!approval || approval.version !== 1 || approval.codeRevision !== revision || !parsed.success
    || parsed.data.codeRevision !== revision || approval.proofHash !== transition.proofHash
    || await eodHash(approval.proof) !== transition.proofHash
    || transition.migrationId !== approved.proof.identity.id) fail("config-code-approval-required");
  assertConfigCapacity(approved, parsed.data);
  return approved;
}

/** Preserve the dated last physical sample when creating the config link.
 * Absence stays unmeasured; the daily monitor obtains the next real sample. */
export async function initializeStorageHistoryConfigurationStatus(env: Env, now = new Date()): Promise<void> {
  if (!env.OPS_DB || !env.EOD_CODE_REVISION) fail("bindings-missing");
  const approved = await loadApproval(env, env.EOD_CODE_REVISION);
  if (!approved) fail("config-source-approval-required");
  const measurement = await read<Record<string, unknown>>(env.OPS_DB, `history-measurement:${approved.codeRevision}`);
  await write(env.OPS_DB, `history-storage-status:${env.EOD_CODE_REVISION}`, cachedStatus(approved, measurement, now), now);
}

/** Writers keep the approved hot window even when a capacity forecast expires;
 * expiration blocks pruning/acceptance, not a return to the larger legacy window. */
export async function loadApprovedStorageHotSessions(env: Env): Promise<260 | 90 | null> {
  if (!env.EOD_CODE_REVISION) return null;
  return (await loadApproval(env, env.EOD_CODE_REVISION))?.proof.model.hotSessions ?? null;
}

async function liveSize(db: D1Database): Promise<number> {
  const result = await db.prepare("SELECT 1 AS history_capacity_probe").all();
  const bytes = result.meta.size_after;
  if (!integer(bytes) || bytes <= 0) fail("physical-size-metadata-unavailable");
  return bytes;
}
async function revisions(env: Env, tickers: string[]): Promise<Map<string, number>> {
  const result = new Map<string, number>();
  for (let offset = 0; offset < tickers.length; offset += 500) {
    const rows = await env.MARKET_DATA_DB!.prepare(`SELECT CAST(t.value AS TEXT) AS ticker,CAST(f.value AS TEXT) AS feed,
      COALESCE(r.revision,0) AS revision FROM json_each(?) t CROSS JOIN json_each(?) f
      LEFT JOIN eod_input_revisions r ON r.ticker=t.value AND r.feed=f.value`).bind(JSON.stringify(tickers.slice(offset, offset + 500)), JSON.stringify(FEEDS))
      .all<{ ticker: string; feed: Feed; revision: number }>();
    for (const row of rows.results) {
      if (!tickers.includes(row.ticker) || !FEEDS.includes(row.feed) || !integer(row.revision)) fail("revision-sample-invalid");
      result.set(`${row.feed}:${row.ticker}`, row.revision);
    }
  }
  if (result.size !== tickers.length * 2) fail("revision-sample-incomplete");
  return result;
}

/** Null means no storage-specific approval: the original legacy proof path
 * remains available. A present but expired/mismatched approval fails closed. */
export async function refreshStorageHistoryMaintenanceEvidence(env: Env, input: {
  tickers: string[]; codeRevision: string; now?: Date;
}): Promise<{ capacity: HistoryCapacityEvidence; readers: HistoryReaderEvidence; hotSessions: 260 | 90; feeds: readonly Feed[];
  sample: { measuredAt: string; sampledSymbols: number; sampledRows: number; proofHash: string; marketPhysicalBytes: number; archivePhysicalBytes: number } } | null> {
  const approved = await loadApproval(env, input.codeRevision);
  if (!approved) return null;
  if (!env.MARKET_DATA_DB || !env.MARKET_HISTORY_DB || !env.OPS_DB) fail("bindings-missing");
  const now = input.now ?? new Date(), { proof } = approved, tickers = population(input.tickers);
  const measurementId = `history-measurement:${input.codeRevision}`;
  let diagnostics: Record<string, unknown> = {};
  try {
    if (await eodHash(tickers) !== proof.tickerHash || new Set(tickers).size !== tickers.length) fail("population-changed-remeasurement-required");
    if (now.getTime() < Date.parse(approved.approvedAt) || now.getTime() >= Date.parse(proof.horizon.expiresAt)) fail("forecast-horizon-expired");
    if (proof.model.fallbackStorage === EOD_YAHOO_ARCHIVE_LAYOUT
      && await env.MARKET_DATA_DB.prepare("SELECT 1 AS present FROM alpaca_daily_bars WHERE feed='yahoo-eod' LIMIT 1").first()) {
      fail("yahoo-eod-retention-sweep-overflow");
    }
    const window = proof.model.hotSessions + proof.model.sweepHeadroomSessions;
    const before = await revisions(env, tickers), stateId = `history-storage-sample:${input.codeRevision}`;
    const saved = await read<{ proofHash: string; rowsHash: string; rows: Sample[] }>(env.OPS_DB, stateId);
    const reusable = new Map<string, Sample>();
    if (saved?.proofHash === approved.proofHash && Array.isArray(saved.rows) && await eodHash(saved.rows) === saved.rowsHash) {
      for (const row of saved.rows) {
        if (row.length !== 4 || !tickers.includes(row[0]) || !FEEDS.includes(row[1]) || !integer(row[2]) || !integer(row[3]) || row[3] > window) fail("sample-integrity");
        if (before.get(`${row[1]}:${row[0]}`) === row[2]) reusable.set(`${row[1]}:${row[0]}`, row);
      }
    }
    for (const feed of FEEDS) {
      const feedWindow = feed === "yahoo-eod" && proof.model.fallbackStorage === EOD_YAHOO_ARCHIVE_LAYOUT ? 0 : window;
      const missing = tickers.filter((ticker) => !reusable.has(`${feed}:${ticker}`));
      for (let offset = 0; offset < missing.length; offset += 80) {
        const selected = missing.slice(offset, offset + 80);
        // At most 80*(retention+sweep+1) indexed rows per admitted query. The
        // extra observation detects overflow rather than truncating its count.
        const rows = await env.MARKET_DATA_DB.prepare(`/* eod-capacity-row-sample */ SELECT CAST(t.value AS TEXT) AS ticker,
          COALESCE(r.revision,0) AS revision,(SELECT COUNT(*) FROM (SELECT 1 FROM alpaca_daily_bars b
            WHERE b.feed=? AND b.ticker=t.value ORDER BY date DESC LIMIT ?)) AS retainedRows
          FROM json_each(?) t LEFT JOIN eod_input_revisions r ON r.feed=? AND r.ticker=t.value ORDER BY ticker`)
          .bind(feed, feedWindow + 1, JSON.stringify(selected), feed).all<{ ticker: string; revision: number; retainedRows: number }>();
        if (rows.results.length !== selected.length) fail("row-sample-incomplete");
        for (const row of rows.results) {
          if (!selected.includes(row.ticker) || !integer(row.revision) || !integer(row.retainedRows)) fail("row-sample-invalid");
          if (row.retainedRows > feedWindow) fail(`${feed}-retention-sweep-overflow`);
          reusable.set(`${feed}:${row.ticker}`, [row.ticker, feed, row.revision, row.retainedRows]);
        }
        const checkpoint = [...reusable.values()].sort((a, b) => `${a[1]}:${a[0]}`.localeCompare(`${b[1]}:${b[0]}`));
        await write(env.OPS_DB, stateId, { proofHash: approved.proofHash, rowsHash: await eodHash(checkpoint), rows: checkpoint }, now);
      }
    }
    const after = await revisions(env, tickers), samples = [...reusable.values()];
    if (samples.length !== tickers.length * 2 || samples.some((row) => after.get(`${row[1]}:${row[0]}`) !== row[2])) fail("inputs-changed-during-measurement");
    const [marketPhysicalBytes, archivePhysicalBytes] = await Promise.all([liveSize(env.MARKET_DATA_DB), liveSize(env.MARKET_HISTORY_DB)]);
    const sampledRows = samples.reduce((sum, row) => sum + row[3], 0), remainingHotRows = proof.model.modeledPriceRows - sampledRows;
    // This coefficient comes from exact populated SQLite table/index pages for
    // the approved full-width hot layout. No JSON-byte estimate or multiplier.
    const priceBytesPerRowBound = Math.ceil(proof.model.priceTableAndIndexBytes / proof.model.modeledPriceRows);
    const fixedArchive=proof.model.currentArchiveForecast
      ? storageArchiveMonitorProjection(proof.model.currentArchiveForecast,proof.horizon,proof.capacity.projectedHistoryBytes,archivePhysicalBytes) : null;
    const additionalArchiveBytes = fixedArchive?.additionalBytes ?? Math.max(0, proof.capacity.projectedHistoryBytes - proof.capacity.liveHistoryBytes);
    const projectedMarket = Math.max(proof.capacity.projectedMarketBytes,
      marketPhysicalBytes + remainingHotRows * priceBytesPerRowBound + proof.capacity.publicationGrowthReserveBytes);
    const projectedHistory = fixedArchive?.projectedBytes ?? Math.max(proof.capacity.projectedHistoryBytes, archivePhysicalBytes + additionalArchiveBytes);
    const capacity: HistoryCapacityEvidence = { measuredAt: now.toISOString(), marketDatabaseBytes: marketPhysicalBytes,
      priceTableAndIndexBytes: proof.model.priceTableAndIndexBytes, priceRows: proof.model.modeledPriceRows,
      retainedPriceRows: proof.model.modeledPriceRows, archiveDatabaseBytes: archivePhysicalBytes, additionalArchiveBytes,
      liveProjection: { baselineMeasuredAt: proof.model.measuredAt, sampledRows, populationSize: tickers.length,
        remainingHotRows, priceBytesPerRowBound, marketBytes: projectedMarket, archiveBytes: projectedHistory } };
    const sample = { measuredAt: now.toISOString(), sampledSymbols: tickers.length, sampledRows, proofHash: approved.proofHash,
      marketPhysicalBytes, archivePhysicalBytes };
    diagnostics = { capacity, readers: proof.readers, sample, horizon: proof.horizon, analysisHash: proof.capacity.analysisHash,
      hotSessions: proof.model.hotSessions, feeds: FEEDS, feedRows: Object.fromEntries(FEEDS.map((feed) => [feed, samples.filter((row) => row[1] === feed).reduce((sum, row) => sum + row[3], 0)])) };
    // loadApproval verified any config-only lineage while retaining the actual
    // original parity date/hash. Its byte-identical reader is applicable here.
    const readers = { ...proof.readers, codeRevision: input.codeRevision };
    diagnostics.readers = readers;
    assertHistoryPruneEvidence(capacity, readers, now, input.codeRevision);
    const measurement = { status: "ready", ...diagnostics };
    await write(env.OPS_DB, measurementId, measurement, now);
    await write(env.OPS_DB, `history-storage-status:${input.codeRevision}`, cachedStatus(approved,measurement,now), now);
    return { capacity, readers, hotSessions: proof.model.hotSessions, feeds: FEEDS, sample };
  } catch (error) {
    const measurement = { status: "failed", ...diagnostics, measuredAt: now.toISOString(),
      horizon: proof.horizon, error: error instanceof Error ? error.message : "measurement-failed" };
    await write(env.OPS_DB, measurementId, measurement, now).catch(() => undefined);
    await write(env.OPS_DB, `history-storage-status:${input.codeRevision}`, cachedStatus(approved,measurement,now), now).catch(() => undefined);
    throw error;
  }
}

/** Independent daily monitor entry point. The full approved population comes
 * from its durable proof; the actual latest catalog detects additions/removals
 * before that prior population can be mistaken for current storage coverage. */
export async function refreshApprovedStorageHistoryCapacity(env: Env, now = new Date()) {
  if (!env.EOD_CODE_REVISION) return null;
  const approved = await loadApproval(env, env.EOD_CODE_REVISION);
  if (!approved) return null;
  if (!env.MARKET_DATA_DB) fail("bindings-missing");
  const current = await env.MARKET_DATA_DB.prepare(`SELECT json_extract(member.value,'$[0]') AS ticker
    FROM eod_publication_pointers h JOIN eod_publications p ON p.id=h.publication_id,
    json_each(CASE WHEN p.payload_codec='json' THEN p.payload_json ELSE '{}' END,'$.rows') member
    WHERE h.scope='history:catalog' AND p.scope=h.scope AND p.status='accepted' ORDER BY ticker LIMIT 10001 /* eod-history-catalog-read */`)
    .all<{ ticker: string }>();
  const tickers = current.results.map((row) => row.ticker);
  if (tickers.length > 10_000 || tickers.some((ticker) => typeof ticker !== "string")
    || await eodHash(tickers) !== approved.proof.tickerHash) {
    const failure = { status: "failed", measuredAt: now.toISOString(), error: "eod-history-storage-capacity-population-changed-remeasurement-required" };
    await write(env.OPS_DB!, `history-storage-status:${env.EOD_CODE_REVISION}`, cachedStatus(approved,failure,now), now);
    fail("population-changed-remeasurement-required");
  }
  return refreshStorageHistoryMaintenanceEvidence(env, { tickers: approved.proof.tickers, codeRevision: env.EOD_CODE_REVISION, now });
}

/** Two small cached Ops records: never hashes the full ticker manifest or reads
 * prices/publications during inexpensive page metadata polling. */
export async function loadStorageHistoryCapacityStatus(env: Env, now = new Date()): Promise<StorageHistoryCapacityStatus | null> {
  if (!env.OPS_DB || !env.EOD_CODE_REVISION) return null;
  const status = await read<StorageHistoryCapacityStatus>(env.OPS_DB, `history-storage-status:${env.EOD_CODE_REVISION}`);
  if (!status) return null;
  if (!digest(status.proofHash) || !Number.isFinite(Date.parse(status.horizonExpiresAt))) fail("cached-status-invalid");
  let renewal: StorageCapacityRenewalPublicStatus | null;
  try {
    const { loadStorageCapacityRenewalStatus } = await import("./eod-storage-capacity-renewal");
    const record = await loadStorageCapacityRenewalStatus(env, now);
    renewal = record ? { status: record.status, stage: record.stage, updatedAt: record.updatedAt,
      nextAttemptAt: record.nextAttemptAt, error: record.error } : null;
  } catch {
    renewal = { status: "unavailable", stage: null, updatedAt: null, nextAttemptAt: null, error: "capacity-renewal-status-unavailable" };
  }
  if (now.getTime() >= Date.parse(status.horizonExpiresAt)) return { ...status, renewal, status: "expired", error: "forecast-horizon-expired" };
  if (status.status === "ready" && (!status.checkedAt || now.getTime() - Date.parse(status.checkedAt) > 86_400_000)) {
    return { ...status, renewal, status: "unmeasured", error: "live-capacity-measurement-stale" };
  }
  return { ...status, renewal };
}

import { authenticateStorageRenewalArchiveContext,storageAcceptedArchiveForecast,validateStorageCurrentArchiveReport } from "./eod-current-archive-validation";
import { eodHash } from "./eod-publication-service";
import { loadEodInputs } from "./eod-runner";
import { expectedEodSession, EOD_PUBLICATION_SCOPES } from "./eod-coordinator";
import { assertEodCutover } from "./eod-rollout-service";
import { loadStorageHistoryMaintenanceApproval, type StorageHistoryMaintenanceApproval } from "./eod-storage-history-capacity";
import { prepareStorageSourceFence } from "./market-storage-fence";
import { loadStorageMigration, storageExecutionRevision } from "./market-storage-control";
import { validateStorageConsumerEvidence, type StorageAcceptanceCapture, type StorageConsumerEvidence,
  type StoragePublicationEvidence, type validateStorageCapacityAnalysis } from "./market-storage-acceptance";
import { MARKET_HISTORY_REQUIRED_CONSUMERS } from "./eod-history-maintenance";
import { EOD_YAHOO_ARCHIVE_LAYOUT, storageFallbackModelValid } from "./eod-storage-layout";
import type { Env } from "./types";

export const STORAGE_CAPACITY_RENEWAL_LEAD_SESSIONS = 5;
// The CLI is bounded to 70 minutes and its workflow to 80; a 90-minute lease lets
// the next two-hour scheduled opportunity recover an abruptly killed runner.
export const STORAGE_CAPACITY_RENEWAL_LEASE_MS = 90 * 60_000;
export type StorageCapacityRenewalStatus = {
  version: 1; codeRevision: string; attemptId: string; status: "running" | "failed" | "completed";
  stage: string; updatedAt: string; leaseUntil: string | null; nextAttemptAt: string | null;
  error: string | null; previousProofHash: string; populationHash: string; progress: Record<string, number | string>;
};
export type StorageCapacityRenewalDue = {
  needed: boolean; reason: "not-activated" | "no-storage-approval" | "population-changed" | "forecast-due" | "current";
  codeRevision: string; previousProofHash: string | null; populationHash: string | null;
  runId: string | null; sessionDate: string | null; remainingSessions: number;
};
type DatabaseCapture = { schemaHash: string; revision: number };
export type StorageCapacityCapture = { version: 1; market: DatabaseCapture; history: DatabaseCapture;
  inputClock: number; populationHash: string; runId: string; sessionDate: string; codeRevision: string; capturedAt: string };
const object = (value: unknown): Record<string, unknown> => value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : {};
const digest = (value: unknown): value is string => typeof value === "string" && /^[a-f0-9]{64}$/.test(value);
const integer = (value: unknown): value is number => typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
function fail(reason: string): never { throw new Error(`eod-capacity-renewal-${reason}`); }
const sorted = (values: string[]) => [...values].sort();
export const storageCapacityRenewalKey = (revision: string): string => `history-capacity-renewal:${revision}`;
async function read<T>(db: D1Database, id: string): Promise<T | null> {
  const raw = await db.prepare("SELECT evidence_json FROM eod_rollout_evidence WHERE id=?").bind(id).first<string>("evidence_json");
  if (!raw) return null;
  try { return JSON.parse(raw) as T; } catch { return fail("stored-json-invalid"); }
}

/** A bounded, read-only due check. It includes the current configuration,
 * verified memberships and active catalog, not just yesterday's catalog rows. */
export async function inspectStorageCapacityRenewal(env: Env, now = new Date()): Promise<StorageCapacityRenewalDue> {
  const codeRevision = env.EOD_CODE_REVISION ?? "";
  const empty = { needed: false, codeRevision, previousProofHash: null, populationHash: null,
    runId: null, sessionDate: null, remainingSessions: 0 };
  if (env.EOD_RUNNER_MODE !== "active" || !env.OPS_DB || !env.MARKET_DATA_DB || !env.MARKET_HISTORY_DB) return { ...empty, reason: "not-activated" };
  const approved = await loadStorageHistoryMaintenanceApproval(env, codeRevision);
  if (!approved) return { ...empty, reason: "no-storage-approval" };
  const sessionDate = await expectedEodSession(env, now);
  if (!sessionDate) fail("calendar-incomplete");
  const inputs = await loadEodInputs(env, sessionDate), populationHash = await eodHash(sorted(inputs.tickers));
  const run = await env.OPS_DB.prepare(`SELECT id FROM eod_runs WHERE mode='active' AND purpose='daily'
    AND status='completed' AND session_date=? ORDER BY completed_at DESC LIMIT 1`).bind(sessionDate).first<{ id: string }>();
  const remaining = await env.MARKET_DATA_DB.prepare(`SELECT session_date FROM market_calendar_sessions
    WHERE session_date>? AND session_date<=? ORDER BY session_date LIMIT 1301`)
    .bind(sessionDate, approved.proof.horizon.lastCoveredSession).all<{ session_date: string }>();
  const changed = populationHash !== approved.proof.tickerHash;
  const due = remaining.results.length <= STORAGE_CAPACITY_RENEWAL_LEAD_SESSIONS
    || now.getTime() >= Date.parse(approved.proof.horizon.expiresAt);
  return { needed: changed || due, reason: changed ? "population-changed" : due ? "forecast-due" : "current", codeRevision,
    previousProofHash: approved.proofHash, populationHash, runId: run?.id ?? null, sessionDate, remainingSessions: remaining.results.length };
}

/** Verify every write guard before trusting its monotonic revision. A released
 * rollback fence stops counting and is explicitly unsuitable for a capture. */
export async function captureOpenStorageDatabase(db: D1Database): Promise<DatabaseCapture> {
  const plan = await prepareStorageSourceFence(db);
  const state = await db.prepare("SELECT status,revision,released_at FROM market_storage_fence WHERE id='default'")
    .first<{ status: string; revision: number; released_at: string | null }>();
  const guards = await db.prepare("SELECT sql FROM sqlite_schema WHERE type='trigger' AND name LIKE 'market_storage_guard_%'").all<{ sql: string }>();
  const normalize = (sql: string) => {
    const input = sql.replace(/^\s*CREATE\s+TRIGGER\s+IF\s+NOT\s+EXISTS\s+/i, "CREATE TRIGGER ");
    let output = "", quote: string | null = null;
    for (let index = 0; index < input.length; index++) {
      const char = input[index];
      if (quote) {
        output += char;
        if (char === quote) {
          if (input[index + 1] === quote) output += input[++index]; else quote = null;
        }
      } else if (["'", '"', "`", "["].includes(char)) { quote = char === "[" ? "]" : char; output += char; }
      else if (!/\s/.test(char)) output += char;
    }
    if (quote) fail("capture-tracking-incomplete");
    return output.replace(/;$/, "");
  };
  const expected = new Set(plan.statements.map((item) => normalize(item.sql)));
  if (!state || state.status !== "open" || state.released_at !== null || !integer(state.revision)
    || guards.results.length !== expected.size || guards.results.some((row) => !expected.has(normalize(row.sql)))) fail("capture-tracking-incomplete");
  return { schemaHash: plan.schemaHash, revision: state.revision };
}
export async function captureStorageCapacityInputs(env: Env, due: StorageCapacityRenewalDue, now = new Date()): Promise<StorageCapacityCapture> {
  if (!due.needed || !due.runId || !due.sessionDate || !due.populationHash || env.EOD_CODE_REVISION !== due.codeRevision) fail("current-publication-required");
  const [market, history, inputClock, current] = await Promise.all([
    captureOpenStorageDatabase(env.MARKET_DATA_DB!), captureOpenStorageDatabase(env.MARKET_HISTORY_DB!),
