  const promoted = await env.OPS_DB.prepare(`INSERT INTO eod_rollout_evidence(id,evidence_json,updated_at)
    SELECT ?,?,? WHERE EXISTS(SELECT 1 FROM eod_rollout_evidence WHERE id=?
